class Solution:
    def longestSubstring(self, s):
        vowels = set('aeiou')
        n = len(s)

        prefix = [0]*(n+1)
        for i in range(n):
            if s[i] in vowels:
                prefix[i+1] = prefix[i] - 2
            else:
                prefix[i+1] = prefix[i] + 1

        stack = []
        for i in range(n+1):
            if not stack or prefix[i] < prefix[stack[-1]]:
                stack.append(i)

        max_len = 0
        start_idx = -1

        for j in range(n, -1, -1):
            while stack and prefix[j] >= prefix[stack[-1]]:
                i = stack.pop()
                length = j - i
                if length > max_len:
                    max_len = length
                    start_idx = i

        return "-1" if max_len == 0 else s[start_idx:start_idx+max_len]
